// Cart amount before rounding to whole yen. `discount` is the customer's
// discount rate (0.1 = 10%), applied once. Carts with 10 or more lines then
// get an extra 5% bulk discount, also applied once.
export function exactTotal(items, discount = 0) {
  const subtotal = items.reduce((sum, item) => sum + item.price * item.qty, 0);
  const bulk = items.length >= 10 ? 0.05 : 0;
  return subtotal * (1 - discount) * (1 - bulk);
}

// Cart total in whole yen. Fractions of a yen are dropped.
export function total(items, discount = 0) {
  // Snap float noise first (1000 * (1 - 0.9) is 99.99999999999997, which must
  // come out as 100, not 99), then drop the fraction.
  const amount = exactTotal(items, discount);
  return Math.floor(Math.round(amount * 1e6) / 1e6);
}

export function itemCount(items) {
  return items.reduce((n, item) => n + item.qty, 0);
}

